// Data access for the naming-queries.ts module. Every query and write its screens make
// goes through here; components do not call the database directly.
//
// Each function returns the Supabase query itself, so callers await it (or call
// .then) and read `{ data, error }` as usual. Functions are grouped by table.
//
// Generated by scripts/codemods/extract-service.mjs and then maintained by hand.
// Keep the "// @table" markers: the codemod reads them when it is run again.

import { createClient } from "@/lib/supabase/client";

const db = () => createClient();

// ── budget_package_sections ───────────────────────────────────────────────────

// @table budget_package_sections
export function deleteBudgetPackageSectionById(id: string | number | boolean) {
  return db().from("budget_package_sections").delete().eq("id", id);
}

// @table budget_package_sections
export function insertBudgetPackageSectionReturning(row: object) {
  return db().from("budget_package_sections").insert([row]).select().single();
}

// @table budget_package_sections
export function listBudgetPackageSections() {
  return db().from("budget_package_sections").select("*").order("sort_order");
}

// @table budget_package_sections
export function listBudgetPackageSectionsWithIsActive() {
  return db().from("budget_package_sections").select("*").eq("is_active", true).order("sort_order");
}

// @table budget_package_sections
export function updateBudgetPackageSectionById(patch: object, id: string | number | boolean) {
  return db().from("budget_package_sections").update(patch).eq("id", id);
}

// ── building_codes ────────────────────────────────────────────────────────────

// @table building_codes
export function listBuildingCodesWithIsActive(columns: string) {
  return db().from("building_codes").select(columns as "*").eq("is_active", true).order("sort_order");
}

// ── companies ─────────────────────────────────────────────────────────────────

// @table companies
export function getCompanyById(id: string | number | boolean, columns: string) {
  return db().from("companies").select(columns as "*").eq("id", id).single();
}

// @table companies
export function listCompanies() {
  return db().from("companies").select("id, name, code").order("name");
}

// @table companies
export function listCompaniesByIds(ids: readonly (string | number)[]) {
  return db().from("companies").select("id, code").in("id", ids);
}

// @table companies
export function listCompaniesOrderedByCode() {
  return db().from("companies").select("id, code, name").order("code");
}

// @table companies
export function updateCompanyById(patch: object, id: string | number | boolean) {
  return db().from("companies").update(patch).eq("id", id);
}

