// ── document_revisions ────────────────────────────────────────────────────────

// @table document_revisions
export function listDocumentRevisionsByDocumentIdsWithIsLatest(documentIds: readonly (string | number)[]) {
  return db()
    .from("document_revisions")
    .select("document_id, sheet_size, revision_code")
    .in("document_id", documentIds)
    .eq("is_latest", true);
}

// ── document_running_numbers ──────────────────────────────────────────────────

// @table document_running_numbers
export function getDocumentRunningNumberByProjectIdAndDisciplineCodeAndDocumentTypeCode(projectId: string | number | boolean, disciplineCode: string | number | boolean, documentTypeCode: string | number | boolean) {
  return db()
    .from("document_running_numbers")
    .select("last_sequence")
    .eq("project_id", projectId)
    .eq("discipline_code", disciplineCode)
    .eq("document_type_code", documentTypeCode)
    .maybeSingle();
}

// @table document_running_numbers
export function upsertDocumentRunningNumber(row: object) {
  return db()
    .from("document_running_numbers")
    .upsert([row], { onConflict: "project_id,discipline_code,document_type_code" });
}

